init(frame: CGRect)
@MainActor @preconcurrency init(frame: CGRect, arSession: ARSession)  // iOS 17
init?(coder: NSCoder)
@MainActor @preconcurrency var captureSession: RoomCaptureSession! { get }
var delegate: (any RoomCaptureViewDelegate)?
@MainActor @preconcurrency var isModelEnabled: Bool { get set }

protocol RoomCaptureViewDelegate: NSCoding {
  func captureView(shouldPresent roomDataForProcessing: CapturedRoomData, error: (any Error)?) -> Bool  // default returns true
  func captureView(didPresent processedResult: CapturedRoom, error: (any Error)?)
}

struct CapturedRoom: Codable, Sendable {
  init(from decoder: any Decoder) throws
  func encode(to encoder: any Encoder) throws
  var identifier: UUID { get }
  var story: Int { get }             // iOS 17
  var version: Int { get }           // iOS 17
  var walls: [CapturedRoom.Surface] { get }
  var doors: [CapturedRoom.Surface] { get }
  var windows: [CapturedRoom.Surface] { get }
  var openings: [CapturedRoom.Surface] { get }
  var floors: [CapturedRoom.Surface] { get }   // iOS 17
  var objects: [CapturedRoom.Object] { get }
  var sections: [CapturedRoom.Section] { get } // iOS 17
  enum Confidence { case high, medium, low }
  struct AttributesCodableRepresentation: Codable { init(attributes: [any CapturedRoomAttribute]); let attributes: [any CapturedRoomAttribute] }  // iOS 17
  enum Error: LocalizedError { case deviceNotSupported, urlInvalidFileExtension, urlInvalidFilePath, urlInvalidScheme, urlMissingFileExtension }
}

struct CapturedRoom.Surface: Codable, Sendable {
  var identifier: UUID { get }
  var parentIdentifier: UUID? { get }            // iOS 17 (window/door -> wall)
  var category: CapturedRoom.Surface.Category { get }
  var confidence: CapturedRoom.Confidence { get }
  var transform: simd_float4x4 { get }
  var dimensions: simd_float3 { get }             // width, height, (depth ~0) bounding box
  var story: Int { get }                          // iOS 17
  var completedEdges: Set<CapturedRoom.Surface.Edge> { get }
  var curve: CapturedRoom.Surface.Curve? { get }
  var polygonCorners: [simd_float3] { get }       // iOS 17, local plane coords
}
enum CapturedRoom.Surface.Category: Codable, Hashable { case floor, door(isOpen: Bool), opening, wall, window }
enum CapturedRoom.Surface.Edge: CaseIterable, Codable { case top, bottom, left, right }
struct CapturedRoom.Surface.Curve: Codable { var startAngle: Measurement<UnitAngle>; var endAngle: Measurement<UnitAngle>; var radius: Float; var center: simd_float2 /* local xz */ }

struct CapturedRoom.Object: Codable, Sendable {
  var identifier: UUID { get }
  var parentIdentifier: UUID? { get }   // iOS 17 (chair -> table, dishwasher -> storage)
  var category: CapturedRoom.Object.Category { get }
  var confidence: CapturedRoom.Confidence { get }
  var transform: simd_float4x4 { get }
  var dimensions: simd_float3 { get }   // bounding box
  var story: Int { get }                // iOS 17
  var attributes: [any CapturedRoomAttribute] { get }   // iOS 17
  func attribute<T>(of attributeType: T.Type) -> T? where T: CapturedRoomAttribute  // iOS 17
}
enum CapturedRoom.Object.Category: CaseIterable, Codable, Hashable {
  case bathtub, bed, chair, dishwasher, fireplace, oven, refrigerator, sink, sofa, stairs, storage, stove, table, television, toilet, washerDryer
  var supportedAttributeTypes: [any CapturedRoomAttribute.Type] { get }      // iOS 17
  var supportedCombinations: [[any CapturedRoomAttribute]] { get }            // iOS 17
  func supportsCombination(_ attributes: [any CapturedRoomAttribute]) -> Bool // iOS 17
}

protocol CapturedRoomAttribute: CaseIterable, RawRepresentable, Sendable where RawValue == String { var shortIdentifier: String { get }; static var parentCategory: CapturedElementCategory? { get } }
enum CapturedElementCategory { case object(CapturedRoom.Object.Category), surface(CapturedRoom.Surface.Category) }
enum ChairType { case dining, stool, swivel, unidentified }
enum ChairArmType { case existing, missing }
enum ChairLegType { case four, star, unidentified }
enum ChairBackType { case existing, missing }
enum SofaType { case rectangular, singleSeat, lShaped, lShapedExtension, unidentified }
enum StorageType { case cabinet, shelf }
enum TableType { case dining, coffee, unidentified }
enum TableShapeType { case rectangular, circularElliptic, lShaped, unidentified }

func export(to url: URL, exportOptions: CapturedRoom.USDExportOptions = .mesh) throws
func export(to url: URL, metadataURL: URL? = nil, modelProvider: CapturedRoom.ModelProvider? = nil, exportOptions: CapturedRoom.USDExportOptions = .mesh) throws  // iOS 17
