struct CapturedRoomData: Codable, Sendable { init(from decoder: any Decoder) throws; func encode(to encoder: any Encoder) throws }
class RoomBuilder {
  init(options: RoomBuilder.ConfigurationOptions)
  func capturedRoom(from capturedRoomData: CapturedRoomData) async throws -> CapturedRoom
  enum BuildError: LocalizedError { case insufficientInput, invalidInput, exceedSceneSizeLimit, internalError, deviceNotSupported }
}
